import {applyCommands, createDocument, type PaintCommand, type PixelDocument} from './pixels.ts';
import {generateEffectCommands} from './effects.ts';

/**
 * Stardrop's entire art pipeline goes through Pixel Workshop's native
 * paint-command engine. Every result is a valid, editable .pixel.json
 * document, including the effects generated by the same FX system as MCP.
 */
export type StardropArtName = 'backdrop'|'moonkeeper'|'star'|'shade'|'beacon'|'tree'|'grass'|'sparkles'|'burst'|'pulse';
export type StardropArt = Record<StardropArtName, PixelDocument>;

export const STARDROP_ASSETS: {key: StardropArtName; label: string; role: string}[] = [
  {key:'backdrop', label:'The Moonlit Vale', role:'4-layer environment'},
  {key:'moonkeeper', label:'The Moonkeeper', role:'6-frame playable character'},
  {key:'star', label:'Fallen Star', role:'4-frame collectible'},
  {key:'shade', label:'Night Shade', role:'4-frame enemy'},
  {key:'beacon', label:'The Last Lantern', role:'6-frame world object'},
  {key:'tree', label:'Elder Pine', role:'2-layer scenery sprite'},
  {key:'grass', label:'Moon Grass', role:'foreground tile'},
  {key:'sparkles', label:'Forest Sparkles', role:'seeded 8-frame FX'},
  {key:'burst', label:'Starlight Burst', role:'seeded 8-frame FX'},
  {key:'pulse', label:'Moonwave', role:'seeded 8-frame FX'},
];

const C = {
  outline:'#10152b', midnight:'#131831', sky:'#1c2747', skyLit:'#324263',
  haze:'#43516c', mist:'#7480a1', moon:'#fff2c5', pale:'#d9ddcf',
  ridge:'#263851', highRidge:'#3e5265', distant:'#506078', forest:'#172f3b',
  pine:'#23434a', pineLit:'#39605e', green:'#385d51', mint:'#6c9680',
  ground:'#243f43', earth:'#354c4a', soil:'#192e39', path:'#5e6067',
  pathLit:'#858088', highlight:'#d6d0a9', gold:'#f7b95e', warm:'#ffdb86',
  spark:'#fff9d7', pink:'#f497b8', violet:'#8273b5', cloak:'#4e497b',
  cloakLit:'#7b71aa', deepViolet:'#332a58', skin:'#d9aa92', skinLit:'#efc6a1',
  hair:'#28213d', boots:'#2b2b41', branch:'#4b3b48', wood:'#674d52',
};

type Pen = {
  p:(x:number,y:number,c:string)=>void;
  r:(x:number,y:number,w:number,h:number,c:string)=>void;
  e:(x:number,y:number,w:number,h:number,c:string)=>void;
  l:(x:number,y:number,x2:number,y2:number,c:string)=>void;
};
function drawing(name:string,w:number,h:number,frames=1,fps=8,moreLayers:{id:string;name:string}[]=[]){
  const ops:PaintCommand[] = [];
  for(const l of moreLayers) ops.push({op:'add_layer',id:l.id,name:l.name});
  if(frames>1){
    ops.push({op:'set_fps',fps});
    for(let i=1;i<frames;i++) ops.push({op:'frame_add',id:'cel-'+i,blank:true});
  }
  const ink=(frame=0,layer='base'):Pen=>{
    const place=(op:string,x:number,y:number,width:number|undefined,height:number|undefined,c:string,extra:Record<string,unknown>={})=>{
      x=Math.round(x);y=Math.round(y);
      const command:PaintCommand={op,layer,frame,x,y,color:c,...extra};
      if(width!==undefined && height!==undefined){
        const ox=x,oy=y;
        x=Math.max(0,x);y=Math.max(0,y);
        const right=Math.min(w,ox+Math.round(width));
        const bottom=Math.min(h,oy+Math.round(height));
        if(right<=x||bottom<=y)return;
        command.x=x;command.y=y;command.width=right-x;command.height=bottom-y;
      }else if(x<0||y<0||x>=w||y>=h)return;
      ops.push(command);
    };
    return {
      p:(x,y,c)=>place('pixel',x,y,undefined,undefined,c),
      r:(x,y,width,height,c)=>place('rect',x,y,width,height,c),
      e:(x,y,width,height,c)=>place('ellipse',x,y,width,height,c),
      l:(x,y,x2,y2,c)=>{
        const limit=(a:number,max:number)=>Math.max(0,Math.min(max-1,Math.round(a)));
        ops.push({op:'line',layer,frame,x:limit(x,w),y:limit(y,h),x2:limit(x2,w),y2:limit(y2,h),color:c});
      },
    };
  };
  return {ink, finish:()=>applyCommands(createDocument(name,w,h,'stardrop-'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-')),ops)};
}
function seeded(seed:number){let s=seed|0;return ()=>{s^=s<<13;s^=s>>>17;s^=s<<5;return(s>>>0)/4294967296;};}

function backdrop(){
  const d=drawing('The Moonlit Vale',192,120,1,8,[
    {id:'mountains',name:'Distant mountains'},
    {id:'forest',name:'Silhouette forest'},
    {id:'garden',name:'Meadow & footpath'},
  ]);
  const sky=d.ink(),range=seeded(17353);
  const shades=['#121930','#17213d','#1a2846','#20304e','#293954','#33445b','#405365'];
  for(let y=0;y<120;y++){
    const t=Math.min(6,Math.floor((y/110)*7));
    sky.r(0,y,192,1,shades[t]);
  }
  sky.e(132,6,42,42,'#ddd0a71c');
  sky.e(137,11,32,32,'#e4d5aa30');
  sky.e(143,15,22,22,'#f7edcf');
  sky.e(148,17,6,5,'#dad1b5');
  sky.e(158,26,3,3,'#d4cab0');
  sky.e(145,29,5,2,'#e7dcbf');
  for(let i=0;i<100;i++){
    const x=Math.floor(range()*190),y=Math.floor(range()*72);
    if(x>131&&x<169&&y>7&&y<44)continue;
    sky.p(x,y,range()>.78?'#e8e0be':'#7485a2');
    if(i%19===0){sky.p(x+1,y,'#8a90a5');sky.p(x,y-1,'#8a90a5');}
  }
  const mountain=d.ink(0,'mountains');
  for(let x=0;x<192;x++){
    const h1=58+Math.sin(x*.058+1.2)*8+Math.sin(x*.119)*4-Math.max(0,19-Math.abs(x-37))*.9;
    const h2=78+Math.sin(x*.047)*8+Math.sin(x*.115+2.3)*4-Math.max(0,15-Math.abs(x-144))*.5;
    mountain.r(x,Math.round(h1),1,120-Math.round(h1),C.distant);
    mountain.r(x,Math.round(h2),1,120-Math.round(h2),C.ridge);
    if(x%3===0 && h1<54)mountain.p(x,Math.round(h1),C.pale);
    if(x%5===0 && h2<77)mountain.p(x,Math.round(h2),C.highRidge);
  }
  // Broken observatory, small and distant, across the valley.
  mountain.r(83,67,12,23,C.forest);
  mountain.r(80,67,18,2,C.forest);
  mountain.r(86,64,7,3,C.forest);
  mountain.r(82,79,14,1,C.highRidge);
  mountain.r(88,70,3,8,'#f6c98799');
  mountain.r(88,64,3,1,C.highRidge);
  const forest=d.ink(0,'forest');
  for(let x=0;x<192;x+=7){
    const y=79+(x*17%13),height=13+(x*11%15);
    forest.r(x+2,y,2,height,C.forest);
    for(let j=0;j<4;j++){
      const width=4+j*2;
      forest.r(x+3-Math.floor(width/2),y+j*4,width,3,j%2?C.forest:C.pine);
    }
  }
  forest.r(0,96,192,24,C.soil);
  const meadow=d.ink(0,'garden');
  meadow.r(0,101,192,19,C.ground);
  meadow.r(0,105,192,15,C.earth);
  for(let x=0;x<192;x++){
    const gy=99+Math.floor(Math.sin(x*.22)*2);
    meadow.r(x,gy,1,3,C.green);
    if(x%3===0)meadow.p(x,gy,C.mint);
  }
  // An old winding path gives the scene some compositional direction.
  for(let y=101;y<120;y++){
    const mid=98+Math.sin((y-101)*.16)*14;
    const half=8+(y-101)*.55;
    meadow.r(Math.round(mid-half),y,Math.round(half*2),1,C.path);
    if(y%3===0)meadow.r(Math.round(mid-half+4),y,Math.round(half*2-8),1,C.pathLit);
  }
  for(let i=0;i<100;i++){
    const x=Math.floor(range()*192),y=101+Math.floor(range()*19);
    if(Math.abs(x-(98+Math.sin((y-101)*.16)*14))<19)continue;
    meadow.p(x,y,range()>.65?C.mint:C.pineLit);
    if(i%11===0){meadow.p(x+1,y,C.gold);meadow.p(x,y-1,C.warm);}
  }
  for(const [x,y] of [[28,111],[62,104],[150,108],[174,114],[13,116]]){
    meadow.e(x,y,5,3,C.deepViolet);meadow.p(x+2,y,C.warm);meadow.p(x+3,y,C.gold);
  }
  return d.finish();
}
function keeper(){
  const d=drawing('The Moonkeeper',20,28,6,9,[{id:'details',name:'Lantern & highlights'}]);
  for(let i=0;i<6;i++){
    const p=d.ink(i),shine=d.ink(i,'details');
    const stride=[0,1,2,0,-1,-2][i],bob=i===0?0:(i%3===0?0:1);
    // Boots / walking cels, with a long indigo cloak.
    p.r(6+Math.max(-1,stride),22,4,5,C.boots);
    p.r(11+Math.min(1,-stride),22,4,5,C.boots);
    p.r(5,18-bob,11,6,C.outline);
    p.r(6,19-bob,10,4,C.deepViolet);
    p.e(4,12-bob,13,13,C.outline);
    p.e(5,12-bob,11,12,C.cloak);
    p.r(6,17-bob,8,5,C.cloakLit);
    p.r(5,21-bob,3,2,C.cloak);
    p.r(13,21-bob,3,2,C.deepViolet);
    // Hood, black hair and warm face under a wide, soft hat.
    p.e(5,4-bob,11,11,C.outline);
    p.e(6,5-bob,9,9,C.skin);
    p.r(6,5-bob,9,3,C.hair);
    p.r(4,3-bob,14,3,C.deepViolet);
    p.r(3,5-bob,15,2,C.outline);
    p.r(5,4-bob,12,2,C.cloak);
    p.p(9,10-bob,C.outline);p.p(13,10-bob,C.outline);
    p.p(10,12-bob,C.skinLit);
    p.r(5,14-bob,3,7,C.cloakLit);
    // Lantern hand moves independently of the cloak.
    const sway=[0,1,2,1,0,-1][i],lx=16+sway,ly=17-bob;
    shine.r(lx-2,ly-3,4,5,C.outline);
    shine.r(lx-1,ly-2,2,3,C.gold);
    shine.p(lx,ly-2,C.spark);
    shine.p(lx-1,ly-3,C.warm);
    shine.r(lx-2,ly+2,4,1,C.wood);
    shine.p(lx-3,ly,C.skinLit);
    shine.p(lx+1,ly-4,'#ffcf8299');
    shine.p(11,7-bob,'#a69dc2');
  }
  return d.finish();
}
function star(){
  const d=drawing('Fallen Star',14,14,4,8,[{id:'glimmer',name:'Inner glimmer'}]);
  for(let f=0;f<4;f++){
    const p=d.ink(f),g=d.ink(f,'glimmer'),len=f%2===0?5:4;
    p.l(7,7-len,7,7+len,C.gold);
    p.l(7-len,7,7+len,7,C.gold);
    p.e(4,4,7,7,C.gold);p.e(5,5,5,5,C.warm);
    g.p(7,7,C.spark);g.p(6,6,C.spark);
    g.p(4-f%2,2,C.warm);g.p(11,11-f%2,C.gold);
    if(f===2){g.p(1,7,'#ffdf9199');g.p(12,7,'#fff9d799');}
  }
  return d.finish();
}
function shade(){
  const d=drawing('Night Shade',18,20,4,7,[{id:'eyes',name:'Eyes & haze'}]);
  for(let f=0;f<4;f++){
    const p=d.ink(f),eyes=d.ink(f,'eyes'),sway=[0,1,0,-1][f];
    p.e(2,4+sway,14,12,C.outline);
    p.e(3,4+sway,12,11,C.deepViolet);
    p.e(5,3+sway,8,6,C.cloak);
    for(let j=0;j<4;j++)p.e(j*4+2,12+sway+(j%2)*2,4,6,j%2?C.outline:C.deepViolet);
    p.p(3,6,C.violet);p.p(14,8,C.violet);
    eyes.r(5,9+sway,3,2,C.pink);eyes.r(11,9+sway,3,2,C.pink);
    eyes.p(6,9+sway,C.spark);eyes.p(12,9+sway,C.spark);
    eyes.p(2,15,'#8870a777');eyes.p(15,16,'#8870a777');
  }
  return d.finish();
}
function beacon(){
  const d=drawing('The Last Lantern',36,42,6,8,[{id:'glow',name:'Animated flame and runes'}]);
  for(let f=0;f<6;f++){
    const p=d.ink(f),gl=d.ink(f,'glow');
    p.e(1,36,34,6,C.soil);
    p.r(6,33,24,5,C.outline);p.r(8,32,20,4,C.highRidge);
    p.r(13,13,10,22,C.outline);p.r(15,13,6,22,C.path);
    p.r(11,12,14,4,C.outline);p.r(12,11,12,2,C.highRidge);
    p.e(8,1,20,18,C.outline);
    p.e(10,2,16,15,C.deepViolet);
    p.e(12,4,12,11,C.gold);
    p.e(14,6,8,8,C.warm);
    p.p(17,8,C.spark);p.p(18,9,C.spark);
    p.r(8,14,20,2,C.highRidge);
    p.r(9,1,18,2,C.outline);p.r(14,0,8,2,C.highRidge);
    p.r(15,30,6,3,C.outline);
    for(const y of [18,24,30]){p.p(14,y,C.highRidge);p.p(21,y,C.highRidge);}
    gl.e(7,0,22,18,'#ffcf8230');
    gl.e(12+f%2,4,12,11,f%2?'#ffdf94aa':'#fff5bfbb');
    gl.p(17+(f%3)-1,7,C.spark);
    gl.p(4,18+f%4,C.violet);gl.p(31,23-f%3,C.gold);
    for(const x of [10,25]){gl.p(x,34,C.warm);gl.p(x+1,34,C.gold);}
  }
  return d.finish();
}
function tree(){
  const d=drawing('Elder Pine',44,64,1,8,[{id:'needles',name:'Moonlit needles'}]);
  const p=d.ink(),leaf=d.ink(0,'needles'),rng=seeded(533);
  p.e(10,59,28,5,'#131c2e99');
  p.r(20,32,7,30,C.outline);p.r(21,31,5,30,C.wood);
  p.r(21,42,2,15,C.branch);
  p.l(23,45,11,35,C.wood);p.l(24,39,35,27,C.wood);
  for(const [x,y,w,h] of [[6,23,32,24],[12,11,27,27],[2,31,23,17],[18,27,24,20],[13,3,19,21]]){
    p.e(x-1,y-1,w+2,h+2,C.outline);
    leaf.e(x,y,w,h,C.pine);
    leaf.e(x+3,y+2,Math.max(2,w-9),Math.max(2,h-8),C.pineLit);
  }
  for(let i=0;i<78;i++){
    const x=3+Math.floor(rng()*38),y=3+Math.floor(rng()*45);
    if((x-22)**2/400+(y-25)**2/650>1)continue;
    leaf.p(x,y,i%4===0?C.mint:C.green);
  }
  leaf.p(11,24,C.moon);leaf.p(33,17,C.mint);
  return d.finish();
}
function grass(){
  const d=drawing('Moon Grass',24,12),p=d.ink(),rng=seeded(17);
  for(let x=0;x<24;x++){
    const h=3+Math.floor(rng()*7);
    p.l(x,11,x+Math.round((rng()-.5)*4),11-h,x%3===0?C.mint:C.pineLit);
    if(x%6===0){p.p(x,5,C.gold);p.p(x+1,6,C.warm);}
  }
  return d.finish();
}
function effect(name:string,w:number,h:number,kind:'sparkles'|'explosion'|'shockwave',ink:string,seed:number){
  const base=createDocument(name,w,h,'stardrop-'+kind);
  return applyCommands(base,generateEffectCommands(base,{kind,ink,seed}));
}
export function createStardropArt():StardropArt {
  const art:StardropArt={
    backdrop:backdrop(),
    moonkeeper:keeper(),
    star:star(),
    shade:shade(),
    beacon:beacon(),
    tree:tree(),
    grass:grass(),
    sparkles:effect('Forest Sparkles',192,120,'sparkles','#d8b6ff',53),
    burst:effect('Starlight Burst',32,32,'explosion','#ffd077',117),
    pulse:effect('Moonwave',48,48,'shockwave','#c9a2ff',5317),
  };
  const clips:Partial<Record<StardropArtName,{name:string;from:number;to:number;fps:number;mode:'loop'|'once'|'pingpong'}[]>>={
    moonkeeper:[
      {name:'idle',from:0,to:0,fps:8,mode:'loop'},
      {name:'walk',from:1,to:5,fps:9,mode:'pingpong'},
      {name:'jump',from:3,to:3,fps:8,mode:'once'},
    ],
    star:[{name:'twinkle',from:0,to:3,fps:8,mode:'loop'}],
    shade:[{name:'float',from:0,to:3,fps:7,mode:'loop'}],
    beacon:[{name:'glow',from:0,to:5,fps:8,mode:'loop'}],
    sparkles:[{name:'ambient',from:0,to:7,fps:8,mode:'loop'}],
    burst:[{name:'burst',from:0,to:7,fps:8,mode:'once'}],
    pulse:[{name:'pulse',from:0,to:7,fps:8,mode:'once'}],
  };
  for(const key of Object.keys(clips) as StardropArtName[])
    art[key]=applyCommands(art[key],clips[key]!.map(clip=>({op:'clip_set',...clip})));
  return art;
}
